import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/technological-inventions/devices-and-measurement/","title":"CH6.3 设备、工具与测量评估 | 英语","lang":"zh-CN","frontmatter":{"title":"CH6.3 设备、工具与测量评估","createTime":"2026-11-20T11:20:00.000Z","permalink":"/english/vocabulary/technological-inventions/devices-and-measurement/"},"readingTime":{"minutes":26.71,"words":8014},"git":{"createdTime":1795161551000},"filePathRelative":"english/vocabulary/technological-inventions/3.devices-and-measurement.md","headers":[],"bulletin":false}`),a={name:`3.devices-and-measurement.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="device" tabindex="-1"><a class="header-anchor" href="#device"><span>Device</span></a></h2><p class="vc-meta"><strong>/dɪˈvaɪs/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>装置，设备，仪器（为特定目的设计）</li><li>手段，策略（文学、修辞手法）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a portable device</td><td>便携设备</td></tr><tr><td>an electronic device</td><td>电子设备</td></tr><tr><td>a device for doing sth</td><td>用来做某事的装置</td></tr><tr><td>a safety device</td><td>安全装置</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows a device that measures the flow of water through the pipe.</p><blockquote><p>该示意图显示了一种测量管道水流量的装置。</p></blockquote><p><strong>Writing Task 2</strong> Personal devices have become the main way people read the news.</p><blockquote><p>个人设备已成为人们获取新闻的主要途径。</p></blockquote><p><strong>Speaking</strong> My phone is the only device I take on trips.</p><blockquote><p>手机是我旅行时唯一带的设备。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>gadget</td><td>小装置</td><td>口语，带调侃色彩</td></tr><tr><td>appliance</td><td>家用电器</td><td>多指家电，范围窄</td></tr><tr><td>instrument</td><td>仪器</td><td>精密测量、专业用途</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>devis</em> ← <em>deviser</em>（划分、安排）← 拉丁 <em>dividere</em></li><li><strong>Family:</strong> device 装置 / devise 设计 / divide 划分 / division 分割</li><li><strong>Memory Tip:</strong> devise（动词）与 device（名词）只差一个字母，读音也不同：/dɪˈvaɪz/ 与 /dɪˈvaɪs/。先想&quot;设计出来的东西就是 device&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 devise 混用，是最常见的拼写错误。</li><li>可数：a device / devices。</li><li>不指大型机器：大型机组用 machine 或 plant。</li></ul></div><div class="vocab-card"><h2 id="appliance" tabindex="-1"><a class="header-anchor" href="#appliance"><span>Appliance</span></a></h2><p class="vc-meta"><strong>/əˈplaɪəns/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>家用电器（尤指厨房、清洁类）</li><li>器具，装置（正式）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>household appliances</td><td>家用电器</td></tr><tr><td>a kitchen appliance</td><td>厨房电器</td></tr><tr><td>energy-efficient appliances</td><td>节能家电</td></tr><tr><td>domestic appliances</td><td>家用器具</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the share of electricity used by household appliances.</p><blockquote><p>该图表显示了家用电器用电所占的比重。</p></blockquote><p><strong>Writing Task 2</strong> Replacing old appliances with efficient ones cuts bills faster than changing habits.</p><blockquote><p>把旧家电换成节能款，比改变习惯更能快速降低账单。</p></blockquote><p><strong>Speaking</strong> The only appliance I&#39;d never give up is the washing machine.</p><blockquote><p>我唯一不会放弃的家电是洗衣机。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>device</td><td>装置</td><td>范围更广，不限于家电</td></tr><tr><td>gadget</td><td>小玩意儿</td><td>口语，指新奇小件</td></tr><tr><td>machine</td><td>机器</td><td>侧重有动力运转的设备</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>apply</em>（应用）+ <em>-ance</em>（名词后缀）</li><li><strong>Family:</strong> appliance 器具 / apply 应用 / application 应用 / applicable 适用的</li><li><strong>Memory Tip:</strong> appliance 是&quot;被应用的东西&quot;——把电用到生活里的器具。所以 household appliances 就是&quot;家用电器&quot;这个固定搭配。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>家电统称 household appliances，用复数。</li><li>拼写 app-li-ance，双 p 单 l。</li><li>不用于工业大型设备，那用 machinery。</li></ul></div><div class="vocab-card"><h2 id="facility" tabindex="-1"><a class="header-anchor" href="#facility"><span>Facility</span></a></h2><p class="vc-meta"><strong>/fəˈsɪləti/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>设施，设备（常用复数 facilities）</li><li>能力，便利条件；（机构的）附属部门</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>sports facilities</td><td>体育设施</td></tr><tr><td>medical facilities</td><td>医疗设施</td></tr><tr><td>a research facility</td><td>研究机构</td></tr><tr><td>with facilities for</td><td>具备……的设施</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the new transport facilities built near the harbour.</p><blockquote><p>该地图显示了港口附近新建的交通设施。</p></blockquote><p><strong>Writing Task 2</strong> Rural clinics lack the facilities to diagnose common conditions, let alone rare ones.</p><blockquote><p>乡村诊所连常见病都缺乏诊断设备，更别说罕见病了。</p></blockquote><p><strong>Speaking</strong> The gym has decent facilities but the pool is always crowded.</p><blockquote><p>健身房设施不错，就是泳池总很挤。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>equipment</td><td>设备</td><td>指可移动的器材，不可数</td></tr><tr><td>infrastructure</td><td>基础设施</td><td>指道路、管网等大系统</td></tr><tr><td>amenities</td><td>生活便利设施</td><td>多指生活服务配套</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>facilitas</em> ← <em>facilis</em>（容易的）← <em>facere</em>（做）</li><li><strong>Family:</strong> facility 设施 / facilitate 促进 / facile 肤浅的；容易的 / fact 事实</li><li><strong>Memory Tip:</strong> fac = 做，facility 本义是&quot;做起来容易&quot;，引申为&quot;让事情容易的条件&quot;——也就是设施。同族的 facilitate（使便利）在本章后面还会遇到。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>表&quot;设施&quot;多用复数：sports facilities。</li><li>表&quot;能力&quot;时不可数：have a facility for languages（有语言天赋）。</li><li>拼写 fac-ility，别写成 <s>facillity</s>。</li></ul></div><div class="vocab-card"><h2 id="equipment" tabindex="-1"><a class="header-anchor" href="#equipment"><span>Equipment</span></a></h2><p class="vc-meta"><strong>/ɪˈkwɪpmənt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>设备，器材（总称，不可数）</li><li>装备，配备</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a piece of equipment</td><td>一件设备</td></tr><tr><td>laboratory equipment</td><td>实验室设备</td></tr><tr><td>heavy equipment</td><td>重型设备</td></tr><tr><td>medical equipment</td><td>医疗设备</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the equipment used to test water quality at each site.</p><blockquote><p>该示意图显示了各站点检测水质所用的设备。</p></blockquote><p><strong>Writing Task 2</strong> Schools in poorer regions often lack basic laboratory equipment.</p><blockquote><p>较贫困地区的学校常常缺少基本的实验设备。</p></blockquote><p><strong>Speaking</strong> The climbing equipment was provided, so we only brought boots.</p><blockquote><p>攀登装备是提供的，我们只带了鞋。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>gear</td><td>装备</td><td>口语，多指运动、户外</td></tr><tr><td>apparatus</td><td>仪器装置</td><td>正式，指成套实验装置</td></tr><tr><td>facilities</td><td>设施</td><td>指场地与配套，不是器材</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>esquiper</em>（为船只配备）← 古诺斯语 <em>skipa</em>（装备船）← <em>skip</em>（船）</li><li><strong>Family:</strong> equipment 设备 / equip 装备 / equipped 配备有……的 / equipage 装备（旧）</li><li><strong>Memory Tip:</strong> 词源与&quot;船&quot;有关：出航前要给船配齐东西，所以 equip 是&quot;配齐装备&quot;。名词 equipment 永远不可数。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>equipments</s> ✘；计件用 a piece of equipment。</li><li>动词是 equip：equip the lab with new tools。</li><li>拼写 equi-pment，注意中间是 p。</li></ul></div><div class="vocab-card"><h2 id="instrument" tabindex="-1"><a class="header-anchor" href="#instrument"><span>Instrument</span></a></h2><p class="vc-meta"><strong>/ˈɪnstrəmənt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>仪器，器械（精密测量、医疗、音乐）</li><li>工具，手段（比喻）；乐器</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a measuring instrument</td><td>测量仪器</td></tr><tr><td>musical instruments</td><td>乐器</td></tr><tr><td>an instrument of policy</td><td>政策工具</td></tr><tr><td>surgical instruments</td><td>手术器械</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the instruments attached to the reactor to record pressure.</p><blockquote><p>该示意图显示了连接在反应器上记录压力的仪器。</p></blockquote><p><strong>Writing Task 2</strong> Standardised tests are a blunt instrument for judging a school.</p><blockquote><p>标准化考试是评判学校的粗糙工具。</p></blockquote><p><strong>Speaking</strong> I play two instruments, neither of them well.</p><blockquote><p>我会两种乐器，都不怎么样。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>tool</td><td>工具</td><td>泛指手工或抽象手段</td></tr><tr><td>device</td><td>装置</td><td>强调功能，不强调精密</td></tr><tr><td>implement</td><td>器具</td><td>多指农具、手工工具</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>instrumentum</em> ← <em>instruere</em>（布置、建造）= <em>in-</em> + <em>struere</em>（堆建）</li><li><strong>Family:</strong> instrument 仪器 / instrumental 起作用的；器乐的 / instrument panel 仪表盘 / instruct 指导</li><li><strong>Memory Tip:</strong> struere 是&quot;堆建&quot;，所以 instrument 原本是&quot;被搭建起来的东西&quot;。形容词 instrumental 引申为&quot;起关键作用的&quot;：play an instrumental role。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>乐器是可数名词：play an instrument。</li><li>instrumental 有两个意思：&quot;器乐的&quot;与&quot;起作用的&quot;，看搭配。</li><li>拼写 in-stru-ment，中间是 -stru-，容易漏成 <s>instrment</s>。</li></ul></div><div class="vocab-card"><h2 id="tool" tabindex="-1"><a class="header-anchor" href="#tool"><span>Tool</span></a></h2><p class="vc-meta"><strong>/tuːl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>工具，器具（手工或机械）</li><li>手段，方法（比喻）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a set of tools</td><td>一套工具</td></tr><tr><td>a powerful tool for</td><td>用于……的有力工具</td></tr><tr><td>use sth as a tool</td><td>把某物当作工具</td></tr><tr><td>machine tools</td><td>机床</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows the simple tools used to cut the stone blocks.</p><blockquote><p>照片显示了切割石块所用的简单工具。</p></blockquote><p><strong>Writing Task 2</strong> Data is only a tool; judgement is what turns it into policy.</p><blockquote><p>数据只是工具，把它变成政策的是判断力。</p></blockquote><p><strong>Speaking</strong> You can&#39;t fix that with the tools we&#39;ve got — we need a proper wrench.</p><blockquote><p>用我们这些工具修不了，得有把合适的扳手。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>instrument</td><td>仪器</td><td>精密、专业，非手工工具</td></tr><tr><td>implement</td><td>器具</td><td>农具、手工器具，偏正式</td></tr><tr><td>utensil</td><td>用具</td><td>多指厨房、餐具</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>tōl</em>（工具），与&quot;准备&quot;同源</li><li><strong>Family:</strong> tool 工具 / toolkit 工具包 / tool bar 工具栏 / machine tool 机床</li><li><strong>Memory Tip:</strong> tool 的比喻义极常用：a tool for change（变革的工具）。写作里比 <s>a method</s> 更有画面，但别过度使用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a tool / tools；统称&quot;工具&quot;也说 tools。</li><li>&quot;用……做工具&quot;是 use sth as a tool，不加 <s>like</s>。</li><li>不指精密仪器，那用 instrument。</li></ul></div><div class="vocab-card"><h2 id="gauge" tabindex="-1"><a class="header-anchor" href="#gauge"><span>Gauge</span></a></h2><p class="vc-meta"><strong>/ɡeɪdʒ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：量规，仪表（压力表、雨量计）</li><li>动词：测量；判断，估计（形势、反应）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a pressure gauge</td><td>压力表</td></tr><tr><td>a rain gauge</td><td>雨量计</td></tr><tr><td>gauge the reaction</td><td>判断反应</td></tr><tr><td>gauge how far</td><td>估计有多远</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows a gauge fitted to the tank to show the water level.</p><blockquote><p>该示意图显示了装在罐上显示水位的水位计。</p></blockquote><p><strong>Writing Task 2</strong> Surveys are a rough way to gauge public opinion on technical issues.</p><blockquote><p>调查是判断公众对技术议题看法的一种粗略方式。</p></blockquote><p><strong>Speaking</strong> It&#39;s hard to gauge how he&#39;ll react until you tell him.</p><blockquote><p>在告诉他之前，很难判断他会怎么反应。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>measure</td><td>测量</td><td>通用词，动名词同形</td></tr><tr><td>meter</td><td>计量表</td><td>指连续读数的表，如电表</td></tr><tr><td>assess</td><td>评估</td><td>只用于抽象判断</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古北法语 <em>gauger</em>（测量水深），词源可能与&quot;横杆&quot;有关</li><li><strong>Family:</strong> gauge 量规；判断 / gauging 测量 / gauge pressure 表压</li><li><strong>Memory Tip:</strong> 名词是&quot;表&quot;，动词是&quot;量&quot;——同形而两类用法。英式拼写 gauge，美式也用 gauge；注意不是 <s>guage</s>。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 g-a-u-g-e，最常见的错拼是 <s>guage</s>。</li><li>动词义&quot;判断&quot;很实用，可替代 judge，但更强调&quot;估量&quot;。</li><li>与 meter 区分：gauge 多指瞬时读数，meter 多指累计计量。</li></ul></div><div class="vocab-card"><h2 id="measure" tabindex="-1"><a class="header-anchor" href="#measure"><span>Measure</span></a></h2><p class="vc-meta"><strong>/ˈmeʒə(r)/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：测量，衡量</li><li>名词：措施，办法；（测量的）尺度，程度</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>measure the impact</td><td>衡量影响</td></tr><tr><td>take measures to</td><td>采取措施</td></tr><tr><td>a measure of</td><td>一定程度的</td></tr><tr><td>safety measures</td><td>安全措施</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart measures output per worker rather than total output.</p><blockquote><p>该图表衡量的是人均产出，而非总产出。</p></blockquote><p><strong>Writing Task 2</strong> Governments should take measures to limit single-use plastics.</p><blockquote><p>政府应当采取措施限制一次性塑料。</p></blockquote><p><strong>Speaking</strong> It&#39;s hard to measure progress when nobody agrees on the goal.</p><blockquote><p>目标都没共识时，很难衡量进展。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>assess</td><td>评估</td><td>侧重判断价值与水平</td></tr><tr><td>gauge</td><td>估量</td><td>偏&quot;凭感觉估&quot;</td></tr><tr><td>step</td><td>步骤；措施</td><td>与 measure 近义，口语更常用</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>mensura</em> ← <em>metiri</em>（测量）</li><li><strong>Family:</strong> measure 测量 / measurement 测量结果 / measurable 可衡量的 / dimension 尺寸</li><li><strong>Memory Tip:</strong> take measures（采取措施）与 measure（测量）同形不同义，靠搭配区分：measure 后面接宾语是&quot;量&quot;，take measures 是&quot;采取行动&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;采取措施&quot;用 take measures，不用 <s>make measures</s>。</li><li>表&quot;一定程度的&quot;用 a measure of，后接不可数名词。</li><li>measurement 可数：take accurate measurements。</li></ul></div><div class="vocab-card"><h2 id="calculate" tabindex="-1"><a class="header-anchor" href="#calculate"><span>Calculate</span></a></h2><p class="vc-meta"><strong>/ˈkælkjuleɪt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>计算，核算（数字）</li><li>推测，估计；打算（be calculated to do）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>calculate the cost</td><td>计算成本</td></tr><tr><td>be calculated to do sth</td><td>意在做成某事</td></tr><tr><td>calculate roughly</td><td>粗略估算</td></tr><tr><td>a calculated risk</td><td>有意承担的风险</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The figures are calculated as a percentage of the total population.</p><blockquote><p>这些数字按占总人口的百分比计算。</p></blockquote><p><strong>Writing Task 2</strong> If the true cost of carbon were calculated, coal would look far less cheap.</p><blockquote><p>如果把碳的真实成本算进去，煤炭就没那么便宜了。</p></blockquote><p><strong>Speaking</strong> I calculated we&#39;d need about two hours to get there.</p><blockquote><p>我算了一下，到那儿大概要两个小时。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>compute</td><td>计算</td><td>更技术化，多指机器运算</td></tr><tr><td>work out</td><td>算出</td><td>口语，最自然</td></tr><tr><td>estimate</td><td>估算</td><td>不追求精确结果</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>calculare</em> ← <em>calculus</em>（计数用的小石子）← <em>calx</em>（石灰石）</li><li><strong>Family:</strong> calculate 计算 / calculation 计算 / calculator 计算器 / calculus 微积分</li><li><strong>Memory Tip:</strong> 古罗马人用小石子摆着数数，那块石子叫 calculus，于是&quot;计算&quot;就叫 calculate，微积分也叫 calculus。这个词源画面很好记。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>calculated 作形容词是&quot;精心策划的&quot;，不是&quot;被计算的&quot;：a calculated insult。</li><li>名词 calculation，别写 <s>calculing</s>。</li><li>重音在第一个音节 /ˈkælkjuleɪt/。</li></ul></div><div class="vocab-card"><h2 id="compute" tabindex="-1"><a class="header-anchor" href="#compute"><span>Compute</span></a></h2><p class="vc-meta"><strong>/kəmˈpjuːt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>计算，运算（多指借助机器或系统）</li><li>（口语）合乎情理（it computes）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>compute the average</td><td>计算平均值</td></tr><tr><td>computing power</td><td>计算能力</td></tr><tr><td>cloud computing</td><td>云计算</td></tr><tr><td>compute a result</td><td>算出结果</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The model computes how much energy each household consumes per year.</p><blockquote><p>该模型计算出每户每年的能耗。</p></blockquote><p><strong>Writing Task 2</strong> The limit is not data but the computing power needed to process it.</p><blockquote><p>瓶颈不在数据，而在处理数据所需的算力。</p></blockquote><p><strong>Speaking</strong> I can&#39;t compute that in my head — give me a second.</p><blockquote><p>我心算不出来，让我想一下。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>calculate</td><td>计算</td><td>通用词，手算机算都可</td></tr><tr><td>reckon</td><td>估算</td><td>英式口语，带主观色彩</td></tr><tr><td>process</td><td>处理</td><td>指数据加工，不强调算出数值</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>computare</em> = <em>com-</em>（一起）+ <em>putare</em>（清算、估算）</li><li><strong>Family:</strong> compute 计算 / computer 计算机 / computation 运算 / computing 计算技术 / repute 名声</li><li><strong>Memory Tip:</strong> putare 是&quot;清算、评估&quot;，加上 com-（一起）就是&quot;汇总核算&quot;。computer 原本指&quot;做计算的人&quot;，20 世纪才变成机器。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>日常口语用 calculate 或 work out，compute 偏技术。</li><li>computing power 是固定说法，不用 <s>computation power</s>。</li><li>重音在第二音节 /kəmˈpjuːt/。</li></ul></div><div class="vocab-card"><h2 id="count" tabindex="-1"><a class="header-anchor" href="#count"><span>Count</span></a></h2><p class="vc-meta"><strong>/kaʊnt/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：计数，数数；算作，重要</li><li>名词：计数，总数</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>count the number of</td><td>数……的数量</td></tr><tr><td>count as</td><td>算作</td></tr><tr><td>count on</td><td>依靠</td></tr><tr><td>every vote counts</td><td>每一票都重要</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart counts only full-time employees, excluding seasonal staff.</p><blockquote><p>该图表只统计全职员工，不含季节性人员。</p></blockquote><p><strong>Writing Task 2</strong> In the long run, what counts is not speed but reliability.</p><blockquote><p>从长远看，重要的不是速度而是可靠性。</p></blockquote><p><strong>Speaking</strong> Don&#39;t count on the weather — it changed three times yesterday.</p><blockquote><p>别指望天气，昨天变了三次。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>tally</td><td>计数</td><td>逐项记录，口语少用</td></tr><tr><td>calculate</td><td>计算</td><td>需运算，不只是数个数</td></tr><tr><td>matter</td><td>重要</td><td>与 count 的&quot;重要&quot;义近似</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>computare</em> → 古法语 <em>conter</em>（计算、叙述）</li><li><strong>Family:</strong> count 计数 / counter 柜台；计数器 / account 账户；说明 / discount 折扣</li><li><strong>Memory Tip:</strong> count 与 compute 同源。account（把账算清→账户；说明）、discount（去掉一部分→折扣）都藏着这个&quot;算&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>表&quot;依靠&quot;用 count on，不用 <s>count with</s>。</li><li>可数名词：a count of 200。</li><li>说&quot;算作&quot;用 count as，别漏 as。</li></ul></div><div class="vocab-card"><h2 id="estimate" tabindex="-1"><a class="header-anchor" href="#estimate"><span>Estimate</span></a></h2><p class="vc-meta"><strong>/ˈestɪmeɪt/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>估计，估算（不追求精确）</li><li>名词：估计，估价；评价（正式）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>it is estimated that</td><td>据估计</td></tr><tr><td>a rough estimate</td><td>粗略估计</td></tr><tr><td>estimate the cost at</td><td>估计成本为</td></tr><tr><td>conservative estimate</td><td>保守估计</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> It is estimated that the project will take four years to complete.</p><blockquote><p>据估计该项目将耗时四年完成。</p></blockquote><p><strong>Writing Task 2</strong> Official estimates of the cost rarely include the damage to ecosystems.</p><blockquote><p>官方对成本的估计很少把生态损害计入。</p></blockquote><p><strong>Speaking</strong> At a rough estimate, we&#39;ll need about fifty chairs.</p><blockquote><p>粗略估计，我们大概需要五十把椅子。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>assess</td><td>评估</td><td>更正式，含判断性质</td></tr><tr><td>calculate</td><td>计算</td><td>追求精确结果</td></tr><tr><td>reckon</td><td>估计</td><td>口语，主观性强</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>aestimare</em>（评价、估价）</li><li><strong>Family:</strong> estimate 估计 / estimation 判断；估计 / overestimate 高估 / underestimate 低估</li><li><strong>Memory Tip:</strong> 前缀一加就成对：overestimate（高估）、underestimate（低估）——写作里评论预测偏差时非常好用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>动词读 /ˈestɪmeɪt/，名词读 /ˈestɪmət/，词尾元音不同。</li><li>固定句型 It is estimated that...，用被动。</li><li>可数：a rough estimate。</li></ul></div><div class="vocab-card"><h2 id="assess" tabindex="-1"><a class="header-anchor" href="#assess"><span>Assess</span></a></h2><p class="vc-meta"><strong>/əˈses/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>评估，评价（质量、影响、风险）</li><li>估价，核定（税额、损失）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>assess the impact</td><td>评估影响</td></tr><tr><td>assess the risk</td><td>评估风险</td></tr><tr><td>assess sb&#39;s needs</td><td>评估某人的需求</td></tr><tr><td>be assessed as</td><td>被评定为</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart assesses each option against cost and reliability.</p><blockquote><p>该图表从成本与可靠性两方面评估了各个方案。</p></blockquote><p><strong>Writing Task 2</strong> It is difficult to assess the long-term effects of a technology while it is still changing.</p><blockquote><p>在一项技术仍在变化时，很难评估其长期影响。</p></blockquote><p><strong>Speaking</strong> The teacher assesses us on the project, not the exam.</p><blockquote><p>老师按项目给我们评分，不看考试。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>evaluate</td><td>评价</td><td>更强调&quot;判定价值&quot;</td></tr><tr><td>appraise</td><td>估价</td><td>正式，多用于资产与绩效</td></tr><tr><td>judge</td><td>判断</td><td>主观性更强</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>assidere</em>（坐在旁边）→ 法官的助手&quot;坐旁核定&quot;</li><li><strong>Family:</strong> assess 评估 / assessment 评估 / assessor 评估员 / session 会期（同源 sedere）</li><li><strong>Memory Tip:</strong> sedere 是&quot;坐&quot;，assess 原指&quot;坐在法官旁边定税&quot;。所以它天然带&quot;核定、裁判&quot;的分量，比 check 重得多。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 ass-ess，双 s；别写成 <s>asses</s>（那是&quot;驴&quot;的复数）。</li><li>名词 assessment，双 s 双 s。</li><li>及物动词，必须带宾语：assess the risk / assess how well it works。</li></ul></div><div class="vocab-card"><h2 id="evaluate" tabindex="-1"><a class="header-anchor" href="#evaluate"><span>Evaluate</span></a></h2><p class="vc-meta"><strong>/ɪˈvæljueɪt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>评价，评估（系统判断好坏、成效）</li><li>求值（数学）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>evaluate the effectiveness</td><td>评估有效性</td></tr><tr><td>evaluate performance</td><td>评估表现</td></tr><tr><td>critically evaluate</td><td>批判性地评价</td></tr><tr><td>evaluate whether</td><td>评估是否</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart evaluates four methods by cost and accuracy.</p><blockquote><p>该图表从成本与准确性两方面评价了四种方法。</p></blockquote><p><strong>Writing Task 2</strong> Policies should be evaluated on outcomes, not on how loudly they were announced.</p><blockquote><p>政策应按结果评估，而不是按宣布得有多响。</p></blockquote><p><strong>Speaking</strong> We&#39;re still evaluating whether the new software is worth the price.</p><blockquote><p>我们还在评估新软件值不值这个价。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>assess</td><td>评估</td><td>与 evaluate 常可互换，更偏&quot;核定&quot;</td></tr><tr><td>appraise</td><td>评价</td><td>正式，多用于绩效与资产</td></tr><tr><td>review</td><td>审查</td><td>侧重回顾检查，含过程</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>évaluer</em> ← <em>value</em>（价值）← 拉丁 <em>valere</em>（有价值）</li><li><strong>Family:</strong> evaluate 评价 / evaluation 评估 / value 价值 / valuable 有价值的 / valid 有效的</li><li><strong>Memory Tip:</strong> val = 有价值、强壮，同族有 value、valid、prevail（占优势）。evaluate 就是&quot;把价值算出来&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>及物：evaluate sth，不接 <s>on</s>。</li><li>名词 evaluation，不是 <s>evaluataion</s>。</li><li>与 assess 近义，同一篇里不要反复换用造成术语混乱。</li></ul></div><div class="vocab-card"><h2 id="accessory" tabindex="-1"><a class="header-anchor" href="#accessory"><span>Accessory</span></a></h2><p class="vc-meta"><strong>/əkˈsesəri/</strong> · noun · 名词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：配件，附件；饰品（常用复数）</li><li>形容词：附属的，附加的（法律：从犯）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>phone accessories</td><td>手机配件</td></tr><tr><td>fashion accessories</td><td>时尚配饰</td></tr><tr><td>an accessory to</td><td>……的附属物；从犯</td></tr><tr><td>accessory equipment</td><td>附属设备</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the camera and its accessories packed in one case.</p><blockquote><p>该示意图显示了相机及其配件装在一个箱子里。</p></blockquote><p><strong>Writing Task 2</strong> Manufacturers profit more from accessories than from the devices themselves.</p><blockquote><p>厂商从配件上赚的钱比从设备本身更多。</p></blockquote><p><strong>Speaking</strong> I bought the phone but skipped all the accessories.</p><blockquote><p>我买了手机，配件一个没买。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>attachment</td><td>附加装置</td><td>指可装拆的附件</td></tr><tr><td>extra</td><td>额外物品</td><td>口语，范围宽</td></tr><tr><td>add-on</td><td>附加组件</td><td>多用于软件与套餐</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>accessorius</em> ← <em>accedere</em>（靠近、附加）= <em>ad-</em> + <em>cedere</em>（走）</li><li><strong>Family:</strong> accessory 配件 / access 进入；通道 / accessible 可到达的 / accession 就职</li><li><strong>Memory Tip:</strong> ced 是&quot;走&quot;，access 是&quot;走到跟前&quot;，accessory 是&quot;跟着一起过来的东西&quot;——所以是附属品。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 acc-ess-ory，双 c 双 s，结尾是 -ory 不是 <s>-ary</s>。</li><li>表&quot;饰品&quot;多用复数 accessories。</li><li>法律义 an accessory to a crime 是&quot;从犯&quot;，别误用为&quot;配件&quot;。</li></ul></div><div class="vocab-card"><h2 id="byproduct" tabindex="-1"><a class="header-anchor" href="#byproduct"><span>Byproduct</span></a></h2><p class="vc-meta"><strong>/ˈbaɪprɒdʌkt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>副产品（生产过程中附带产生）</li><li>意外结果，副作用（常含贬义）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a byproduct of</td><td>……的副产品</td></tr><tr><td>an industrial byproduct</td><td>工业副产品</td></tr><tr><td>a harmful byproduct</td><td>有害的副产物</td></tr><tr><td>a byproduct of growth</td><td>增长的副产物</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how the byproduct of refining is reused as fuel.</p><blockquote><p>该示意图显示了炼制的副产品如何被再利用为燃料。</p></blockquote><p><strong>Writing Task 2</strong> Traffic congestion is a byproduct of cheap cars and poor planning.</p><blockquote><p>交通拥堵是廉价汽车与糟糕规划的副产物。</p></blockquote><p><strong>Speaking</strong> The mess in the kitchen is just a byproduct of good cooking.</p><blockquote><p>厨房一团乱，不过是好厨艺的副产品。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>spin-off</td><td>衍生结果</td><td>多指有益的衍生产品</td></tr><tr><td>side effect</td><td>副作用</td><td>多用于药物、政策</td></tr><tr><td>residue</td><td>残余物</td><td>指物理残留，不含&quot;附带产生&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>by-</em>（旁的、副的）+ <em>product</em>（产物）</li><li><strong>Family:</strong> byproduct 副产品 / bylaw 附例 / bypass 绕过 / bystander 旁观者</li><li><strong>Memory Tip:</strong> by- 表示&quot;次要、旁边&quot;：byproduct（副产品）、bypass（旁路）、bystander（旁观者）。英式也写 by-product，带连字符。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式常写 by-product，美式 byproduct，同一篇保持一致。</li><li>可数：a byproduct of the process。</li><li>别与 spin-off 混：byproduct 中性偏贬，spin-off 常指有益的衍生品。</li></ul></div><div class="vocab-card"><h2 id="auxiliary" tabindex="-1"><a class="header-anchor" href="#auxiliary"><span>Auxiliary</span></a></h2><p class="vc-meta"><strong>/ɔːɡˈzɪliəri/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：辅助的，备用的</li><li>名词：辅助设备；帮手；（语法）助动词</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>auxiliary equipment</td><td>辅助设备</td></tr><tr><td>an auxiliary power supply</td><td>备用电源</td></tr><tr><td>auxiliary staff</td><td>辅助人员</td></tr><tr><td>auxiliary verb</td><td>助动词</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the auxiliary pump that starts when the main one fails.</p><blockquote><p>该示意图显示了主泵故障时启动的辅助泵。</p></blockquote><p><strong>Writing Task 2</strong> Hospitals rely on auxiliary staff who are rarely mentioned in budgets.</p><blockquote><p>医院依赖辅助人员，而预算里很少提到他们。</p></blockquote><p><strong>Speaking</strong> The building has an auxiliary generator for power cuts.</p><blockquote><p>这栋楼有备用发电机应对停电。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>backup</td><td>备用的</td><td>更口语，强调&quot;顶上&quot;作用</td></tr><tr><td>supplementary</td><td>补充的</td><td>强调&quot;额外增加&quot;</td></tr><tr><td>secondary</td><td>次要的</td><td>强调等级低，非&quot;辅助&quot;</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>auxilium</em>（帮助）← <em>augere</em>（增加）</li><li><strong>Family:</strong> auxiliary 辅助的 / aux 辅助接口（缩写）/ augment 增加 / auction 拍卖（同源&quot;加价&quot;）</li><li><strong>Memory Tip:</strong> aug = 增加，帮助就是&quot;给对方加点力量&quot;。augment（增大）、auction（竞价递增）都从这个&quot;加&quot;来。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 aux-iliary，容易漏 i：<s>auxilary</s> ✘。</li><li>语法术语 auxiliary verb 是&quot;助动词&quot;，别译成&quot;辅助动词&quot;。</li><li>作名词指人或设备均可，看语境。</li></ul></div><div class="vocab-card"><h2 id="versatile" tabindex="-1"><a class="header-anchor" href="#versatile"><span>Versatile</span></a></h2><p class="vc-meta"><strong>/ˈvɜːsətaɪl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>多用途的，通用的（工具、材料）</li><li>多才多艺的，适应力强的（人）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a versatile tool</td><td>多用途工具</td></tr><tr><td>a versatile material</td><td>多用途材料</td></tr><tr><td>a versatile performer</td><td>多才多艺的表演者</td></tr><tr><td>highly versatile</td><td>用途极广的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows why bamboo is such a versatile building material.</p><blockquote><p>该示意图说明了竹子为何是如此多用途的建筑材料。</p></blockquote><p><strong>Writing Task 2</strong> Generalists are more versatile, but specialists are easier to hire for a single task.</p><blockquote><p>通才适应力更强，但专才在单一任务上更好用。</p></blockquote><p><strong>Speaking</strong> A wok is the most versatile pan in my kitchen.</p><blockquote><p>炒锅是我厨房里最万能的锅。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>adaptable</td><td>适应性强的</td><td>多形容人或系统</td></tr><tr><td>all-round</td><td>全面的</td><td>口语，形容能力</td></tr><tr><td>multifunctional</td><td>多功能的</td><td>只形容设备功能</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>versatilis</em> ← <em>versare</em>（反复转动）← <em>vertere</em>（转）</li><li><strong>Family:</strong> versatile 多用途的 / version 版本 / convert 转换 / reverse 反转</li><li><strong>Memory Tip:</strong> vert/vers = 转，能&quot;转得开&quot;的东西就是多用途的。同一词根串起 convert、reverse、version、diverse。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>重音在第一音节 /ˈvɜːsətaɪl/，结尾读 /taɪl/ 不是 /tl/。</li><li>形容人时是&quot;多才多艺&quot;，不是&quot;多变的&quot;（那是 <s>changeable</s>）。</li><li>拼写 vers-at-ile，注意中间 a。</li></ul></div><div class="vocab-card"><h2 id="add" tabindex="-1"><a class="header-anchor" href="#add"><span>Add</span></a></h2><p class="vc-meta"><strong>/æd/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>添加，加上；把……相加</li><li>补充说，进一步说</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>add to</td><td>增加，加剧</td></tr><tr><td>add up to</td><td>总计达</td></tr><tr><td>add value</td><td>增值</td></tr><tr><td>add that</td><td>补充说</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart adds the cost of maintenance to the initial price.</p><blockquote><p>该图表把维护成本加到初始价格上。</p></blockquote><p><strong>Writing Task 2</strong> Automation adds efficiency but removes the routine work people take pride in.</p><blockquote><p>自动化提高了效率，却也抹掉了人们引以为傲的常规工作。</p></blockquote><p><strong>Speaking</strong> Add a bit more salt and it&#39;ll be perfect.</p><blockquote><p>再加点盐就完美了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>append</td><td>附加</td><td>正式，多指文末追加</td></tr><tr><td>supplement</td><td>补充</td><td>强调补足不足</td></tr><tr><td>insert</td><td>插入</td><td>指放进中间位置</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>addere</em> = <em>ad-</em>（向）+ <em>dare</em>（给）</li><li><strong>Family:</strong> add 添加 / addition 增加；加法 / additional 额外的 / additive 添加剂</li><li><strong>Memory Tip:</strong> ad + dare（给）= 往上面再给一点。add to 是&quot;加剧&quot;（This adds to the problem），add up to 是&quot;合计为&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;加剧&quot;用 add to，不省略 to：<s>It adds the problem</s> ✘。</li><li>addition 是名词，in addition to 是&quot;除……之外&quot;。</li><li>add up to 后接总数，不接被加的项。</li></ul></div><div class="vocab-card"><h2 id="accumulate" tabindex="-1"><a class="header-anchor" href="#accumulate"><span>Accumulate</span></a></h2><p class="vc-meta"><strong>/əˈkjuːmjəleɪt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>积累，积聚（逐渐增多）</li><li>堆积，聚积（物）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>accumulate wealth</td><td>积累财富</td></tr><tr><td>accumulate evidence</td><td>积累证据</td></tr><tr><td>accumulated damage</td><td>累积的损害</td></tr><tr><td>gradually accumulate</td><td>逐渐积累</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> Waste accumulates in the harbour because the outlet is too narrow.</p><blockquote><p>由于排水口太窄，废物在港湾里堆积。</p></blockquote><p><strong>Writing Task 2</strong> Small inefficiencies accumulate into a serious loss of productivity.</p><blockquote><p>微小的低效累积起来，会造成严重的生产力损失。</p></blockquote><p><strong>Speaking</strong> Books just accumulate in my flat — I never throw any away.</p><blockquote><p>我家里书越堆越多，一本都舍不得扔。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>build up</td><td>逐步积累</td><td>口语，强调过程</td></tr><tr><td>amass</td><td>积聚</td><td>多指财富、藏品，语气体量大</td></tr><tr><td>pile up</td><td>堆积</td><td>口语，带&quot;乱堆&quot;画面</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>accumulare</em> = <em>ad-</em>（向）+ <em>cumulus</em>（堆）</li><li><strong>Family:</strong> accumulate 积累 / accumulation 积累 / cumulative 累积的 / cumulus 积云</li><li><strong>Memory Tip:</strong> cumulus 是&quot;堆&quot;，气象里的积云就叫 cumulus——一朵朵堆起来的云。cumulative effect（累积效应）是写作高频搭配。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不及物也常用：Dust accumulates quickly。</li><li>名词 accumulation 不可数居多：the accumulation of data。</li><li>拼写 acc-umulate，双 c 单 m。</li></ul></div><div class="vocab-card"><h2 id="assemble" tabindex="-1"><a class="header-anchor" href="#assemble"><span>Assemble</span></a></h2><p class="vc-meta"><strong>/əˈsembl/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>组装，装配（把零件装成整体）</li><li>集合，聚集（人）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>assemble a machine</td><td>组装机器</td></tr><tr><td>assemble a team</td><td>组建团队</td></tr><tr><td>flat-pack to assemble</td><td>需自行组装的平板家具</td></tr><tr><td>fully assembled</td><td>组装完成的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how the frame is assembled from six identical parts.</p><blockquote><p>该示意图显示了框架如何由六个相同部件组装而成。</p></blockquote><p><strong>Writing Task 2</strong> Products are designed in one country, assembled in another and sold in a third.</p><blockquote><p>产品在一国设计、另一国组装、第三国销售。</p></blockquote><p><strong>Speaking</strong> It took me three hours to assemble that bookshelf.</p><blockquote><p>我花了三个小时才把那个书架装好。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>put together</td><td>组装</td><td>口语，最自然</td></tr><tr><td>construct</td><td>建造</td><td>强调从无到有地建起</td></tr><tr><td>gather</td><td>聚集</td><td>只用于人或物的聚拢</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>assembler</em> ← 拉丁 <em>assimulare</em> = <em>ad-</em> + <em>simul</em>（一起）</li><li><strong>Family:</strong> assemble 组装；集合 / assembly 装配；集会 / assembly line 流水线 / resemble 相似</li><li><strong>Memory Tip:</strong> simul = 一起，同族有 similar（相似的）、simultaneous（同时的）。assembly line（流水线）正是&quot;把人聚到一起装东西&quot;的地方。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词 assembly 既指&quot;装配&quot;也指&quot;集会&quot;，注意上下文。</li><li>拼写 ass-emble，双 s，结尾 -ble。</li><li>说&quot;自行组装&quot;用 self-assembly 或 flat-pack，不逐字直译。</li></ul></div><div class="vocab-card"><h2 id="gather" tabindex="-1"><a class="header-anchor" href="#gather"><span>Gather</span></a></h2><p class="vc-meta"><strong>/ˈɡæðə(r)/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>聚集，集合（人或物）</li><li>收集（信息、证据）；采集（作物）；推断</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>gather information</td><td>收集信息</td></tr><tr><td>gather around</td><td>围拢过来</td></tr><tr><td>gather evidence</td><td>收集证据</td></tr><tr><td>gather that</td><td>推测，了解到</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how data is gathered from sensors across the site.</p><blockquote><p>该示意图显示了如何从场地各处传感器收集数据。</p></blockquote><p><strong>Writing Task 2</strong> Satellites gather more climate data in a day than researchers once collected in a year.</p><blockquote><p>卫星一天收集的气候数据，比研究者过去一年收集的还多。</p></blockquote><p><strong>Speaking</strong> A crowd gathered to watch them raise the bridge section.</p><blockquote><p>一群人聚过来看他们吊起桥段。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>collect</td><td>收集</td><td>更强调&quot;逐个取回&quot;</td></tr><tr><td>assemble</td><td>集合</td><td>更正式，多指有组织地聚</td></tr><tr><td>accumulate</td><td>积累</td><td>强调数量逐渐增加</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>gaderian</em>（聚拢），与 <em>together</em> 同源</li><li><strong>Family:</strong> gather 聚集 / gathering 聚会 / together 一起 / altogether 完全</li><li><strong>Memory Tip:</strong> gather 与 together 同源，都是&quot;合成一堆&quot;。I gather that...（我推测）是口语里很地道的用法。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 g-a-t-h-e-r，别写成 <s>gether</s>。</li><li>及物义&quot;收集&quot;直接带宾语：gather data。</li><li>gathering 作名词指&quot;聚会&quot;，不用来形容&quot;收集&quot;这个动作。</li></ul></div><div class="vocab-card"><h2 id="attach" tabindex="-1"><a class="header-anchor" href="#attach"><span>Attach</span></a></h2><p class="vc-meta"><strong>/əˈtætʃ/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>系上，附上，连接（物理）</li><li>附加（文件、条件）；使依附；使重视（attach importance to）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>attach sth to sth</td><td>把某物固定到某物上</td></tr><tr><td>attach a file</td><td>附加文件</td></tr><tr><td>be attached to</td><td>依恋；附属于</td></tr><tr><td>attach importance to</td><td>重视</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows a sensor attached to the underside of the bridge.</p><blockquote><p>该示意图显示了固定在桥底的传感器。</p></blockquote><p><strong>Writing Task 2</strong> People become attached to technologies long before they understand them.</p><blockquote><p>人们往往在理解某项技术之前就已经离不开它了。</p></blockquote><p><strong>Speaking</strong> I&#39;ve attached the photos to the email — tell me if they don&#39;t open.</p><blockquote><p>照片我附在邮件里了，打不开告诉我。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>fasten</td><td>系紧</td><td>强调固定牢靠</td></tr><tr><td>affix</td><td>贴上</td><td>正式，多指印章、标签</td></tr><tr><td>connect</td><td>连接</td><td>可指抽象关系，不必然接触</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>atachier</em>（固定），可能与&quot;钉子&quot;有关</li><li><strong>Family:</strong> attach 附上 / attachment 附件；依恋 / detached 独立的；超然的 / detach 拆下</li><li><strong>Memory Tip:</strong> 一对反义很好用：attach（附上）↔ detach（拆下）；attached（依恋的）↔ detached（超然的，如 a detached observer）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 to：attach the label to the box。</li><li>be attached to 是&quot;依恋&quot;，不是&quot;被附上&quot;这么简单，注意语境。</li><li>拼写 at-tach，双 t。</li></ul></div><div class="vocab-card"><h2 id="belong" tabindex="-1"><a class="header-anchor" href="#belong"><span>Belong</span></a></h2><p class="vc-meta"><strong>/bɪˈlɒŋ/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>属于（belong to）</li><li>应在（某处），适合待在</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>belong to</td><td>属于</td></tr><tr><td>belong in</td><td>应归入；适合待在</td></tr><tr><td>a sense of belonging</td><td>归属感</td></tr><tr><td>personal belongings</td><td>个人物品</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The artefacts belong to a period when metalworking was still new.</p><blockquote><p>这些器物属于金属加工刚刚出现的时期。</p></blockquote><p><strong>Writing Task 2</strong> A sense of belonging matters more to wellbeing than income does.</p><blockquote><p>归属感对幸福感的重要性超过收入。</p></blockquote><p><strong>Speaking</strong> These keys belong to the flat upstairs, not to us.</p><blockquote><p>这些钥匙是楼上那户的，不是我们的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>pertain to</td><td>属于；关于</td><td>正式，多指规则、范畴</td></tr><tr><td>own</td><td>拥有</td><td>主动关系，belong 是被动归属</td></tr><tr><td>fit in</td><td>融入</td><td>口语，指人际关系</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>longen</em>（适合、属于）前加 <em>be-</em></li><li><strong>Family:</strong> belong 属于 / belonging 归属感 / belongings 随身物品 / longing 渴望（同源 <em>longen</em>）</li><li><strong>Memory Tip:</strong> belong to 不能用于被动，也不能用进行时：<s>It is belonged to me</s> ✘。belongings 永远用复数，指&quot;随身物品&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>无被动、无进行时：The book belongs to her。</li><li>个人物品说 personal belongings，用复数。</li><li>belong to（属于）与 belong in（该放在）不同：This belongs in the drawer。</li></ul></div>`,24)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};